const MISSIONS=[
{name:'Ambush',group:'first',pages:'pp. 213–214',comp:'restricted',note:'Reroll Random Duration',duration:'Unlimited',setup:'The side that chooses their home edge is the Defender. The map-selecting side is the Attacker.',objectives:'None.',deployment:'Defender uses standard deployment. Attacker splits units into two even groups and deploys one group from each short edge. A ’Mech-only group may use Combat Drop. Attacker automatically wins Initiative for the first two turns.',victory:'The last side with a non-crippled unit left is the victor.',decisions:['Roll off to choose maps; the loser chooses home edge.','Attacker divides its force into two groups and chooses whether to use Combat Drop for a ’Mech-only group.'],refs:'pp. 213–214'},
{name:'Annihilation',group:'first',pages:'pp. 214–215',comp:'master',note:'Reroll Random Duration; then roll 1D6 for an additional Master Complication on 4+. Reroll duplicates, Random Duration, and a second Edge/Fog of War type.',duration:'Unlimited',setup:'Standard.',objectives:'None.',deployment:'Roll 1D6: 1–2 uses standard deployment; 3–6 deploys from the short edges instead of the long edges.',victory:'The last side with a non-crippled unit left is the victor.',decisions:['Roll for deployment edge orientation after complications.'],refs:'pp. 213–215'},
{name:'Dominate',group:'first',pages:'p. 215',comp:'restricted',note:'Reroll Random Duration',duration:'8 turns',setup:'Standard, but both sides must choose home edges from the short edges.',objectives:'None.',deployment:'Standard deployment.',victory:'Unit Victory Points. A side may move units off the battlefield via the opponent’s home edge on Turn 6 or later; remove each such unit and score its Unit VP value.',decisions:['Both players choose short-edge home edges during setup.'],refs:'pp. 213, 215, 227'},
{name:'Extraction',group:'first',pages:'p. 215',comp:'restricted',note:'',duration:'8 turns unless Random Duration',setup:'The map-selecting side is the Attacker; the home-edge-selecting side is the Defender. Forbidden maps: Box Canyon (paper), Crystalline Canyon (all versions).',objectives:'None.',deployment:'Defender splits its force into two even groups. Attacker chooses one group, which deploys in legal hexes within 2 hexes of Hex 1509 (left mapsheet if two maps). Remaining Defender units enter from its home edge on Turn 1. Attacker uses standard deployment. With BFS, Attacker may not place emplacements, minefields, or artillery pre-designated hexes within 2 hexes of Hex 1509.',victory:'Unit Victory Points.',decisions:['Choose legal maps and place the selected Defender half around Hex 1509.','If BFS is used, keep restricted Asset placement clear.'],refs:'pp. 213, 215, 227'},
{name:'Focal Point',group:'first',pages:'p. 216',comp:'restricted',note:'',duration:'8 turns unless Random Duration',setup:'Standard. Forbidden maps: Box Canyon (paper), Crystalline Canyon (all versions).',objectives:'Place one objective on Hex 1509 (left mapsheet if two maps). It has a control radius of 2 hexes and no objective variants.',deployment:'Standard deployment.',victory:'The controller, if any, receives 3 Victory Points in the End Phase of each turn.',decisions:['Choose a legal map and place/adjust the Hex 1509 objective if terrain makes it inaccessible.'],refs:'pp. 213, 216, 231–232'},
{name:'General Melee',group:'first',pages:'p. 216',comp:'restricted',note:'Fog of War is automatically active with the Thicker Fog variant.',duration:'8 turns',setup:'Standard.',objectives:'None.',deployment:'Forces do not move onto the battlefield. Each player has a deployment zone. Alternate placing Fog of War counters 6–7 hexes from each home edge (rows -07/-08 and -11/-12). Reveal and replace all counters before Turn 1.',victory:'Unit Victory Points.',decisions:['Set deployment zones and place/reveal Fog of War counters; use the automatic Thicker Fog variant.'],refs:'pp. 213, 216, 229'},
{name:'Control the Field',group:'second',pages:'pp. 214–215',comp:'master',note:'',duration:'8 turns unless Random Duration',setup:'Standard.',objectives:'Roll 1D6: 1–4 standard placement, 5–6 hidden placement. Place four counters, two per side, with one on each mapsheet/area. Apply column and 5-hex-from-home-edge restrictions. Roll control radius: 1–2 = 0, 3–5 = 1, 6 = 2 hexes. No variants.',deployment:'Standard deployment.',victory:'If a side controls at least one friendly and one enemy counter, it gains 1 VP in the End Phase, cumulative up to 2 VP per turn.',decisions:['Resolve standard vs hidden objective placement and alternate placement between sides.','Choose legal objective hexes and record hidden positions if applicable.'],refs:'pp. 214, 227, 232'},
{name:'Hold the Line',group:'second',pages:'p. 216',comp:'master',note:'',duration:'8 turns unless Random Duration',setup:'Standard.',objectives:'Place three counters: one exactly 7 hexes from the map-selecting side’s home edge; one 7–10 hexes from the other side’s edge; then one more using the first rule. Each is 8–12 hexes from any other. Roll one radius for all: 1–2 = 0, 3–5 = 1, 6 = 2. No variants.',deployment:'Standard deployment.',victory:'Control two of three counters: 1 VP in the End Phase. Control all three: 2 VP.',decisions:['Alternate placement as specified, starting with the map-selecting side.','Choose legal locations and resolve the shared control-radius roll.'],refs:'pp. 213, 216, 232'},
{name:'Objective Raid',group:'second',pages:'p. 217',comp:'master',note:'',duration:'8 turns unless Random Duration',setup:'Standard.',objectives:'Roll 1D6+6 for 7–12 counters. Alternate placement, starting with the player who chose home edge. Each is 7+ hexes from that side’s home edge and at least 3 hexes from other objectives. Roll radius: 1–3 = 0, 4–6 = 1. All are Potential Objectives; roll variants: 1–3 Fragile, 4–5 Mobile, 6 both.',deployment:'Standard deployment.',victory:'Each player gains 1 VP for each confirmed objective they control in the End Phase of each turn.',decisions:['Place and identify all objective counters, resolve Potential Objective scans, and apply Fragile/Mobile rules.'],refs:'pp. 213, 217, 232–233'},
{name:'Sensor Check',group:'second',pages:'p. 217',comp:'master',note:'',duration:'8 turns unless Random Duration',setup:'Standard.',objectives:'None.',deployment:'Standard deployment.',victory:'Units can scan enemy units. A unit that successfully scanned at least one enemy unit may leave via its home edge on Turn 5+. The side gains 1 VP per enemy unit successfully scanned; repeated scans count.',decisions:['Track scans per unit and choose when eligible units leave via their home edge.'],refs:'pp. 213, 217, 233'},
{name:'Steel Rain',group:'second',pages:'p. 218',comp:'restricted',note:'',duration:'8 turns unless Random Duration',setup:'Determine maps normally. Roll off Attacker/Defender. After objective placement, Attacker selects home edge first.',objectives:'Defender places five Mobile Objectives with control radius 0. Each is at least 5 hexes from any other and any home edge.',deployment:'Attacker standard deployment. Defender ’Mechs use Combat Drop: half on Turn 1 (round up), half on Turn 2. Defender non-’Mechs enter from home edge on Turn 1.',victory:'Attacker may leave via its home edge. Carried-off objectives remain controlled. From Turn 3, Attacker gains 1 VP per controlled objective; Defender gains 1 VP per controlled and 1 VP per uncontrolled objective. From Turn 8, Attacker’s controlled-objective value becomes 2 VP each.',decisions:['Resolve Attacker/Defender, place five Mobile Objectives, and track Combat Drop arrival.'],refs:'pp. 213, 218, 227, 232'},
{name:'Urban Sweep',group:'second',pages:'p. 218',comp:'master',note:'',duration:'8 turns unless Random Duration',setup:'Roll off to determine map selector. Selected maps should have at least six printed buildings; if not, have six building counters available.',objectives:'Place six objectives, each in a separate building hex at least 4 hexes from any home edge. The map-nonselecting player places the first; alternate. Objectives are at ground level, not roofs.',deployment:'Standard deployment.',victory:'Units scan objectives normally while their building stands. On a successful scan, roll 1D6; 4+ awards 2 VP, rerollable with Edge. Each side can claim the VP from a given counter only once; a successful-intel counter is removed at the start of the next turn. A collapsed building removes its counter and the side that triggered the collapse loses 2 VP.',decisions:['Provide/choose legal building hexes, alternate objective placement, and track scans, intel, removals, and collapse penalties.'],refs:'pp. 213, 218, 229, 233'}];
const MASTER={2:'No Complication',3:'Knife-Fight',4:'Edge',5:'Edge: Commanders',6:'Random Duration',7:'Battlefield Conditions',8:'ECM Interference',9:'Fog of War',10:'Fog of War: Thicker Fog',11:'Waves',12:'No Complication'};
const RESTRICTED={1:'No Complication',2:'Edge',3:'Edge: Commanders',4:'Random Duration',5:'Battlefield Conditions',6:'ECM Interference'};
const CONDITIONS={2:'Extreme Cold — roll 1D6 for level',3:'Extreme Cold — roll 1D6 for level',4:'Wind',5:'Snowfall',6:'Night',7:'Roll twice; ignore further 7s',8:'Rain',9:'Gravity — roll 1D6 for level',10:'Low Visibility',11:'Extreme Heat — roll 1D6 for level',12:'Extreme Heat — roll 1D6 for level'};
let state={config:null,mission:null,complication:null,log:[]};const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)],roll=n=>Math.floor(Math.random()*n)+1,fmt=n=>n.toLocaleString('en-US');
function config(){return{scale:Math.max(1,Math.min(20,Number($('#scale').value)||3)),selection:$('input[name="selection"]:checked').value,manual:$('#manual-mission').value,bfs:$('#bfs').checked,options:$$('.check-list input:checked').map(x=>x.value),mapMode:$('#map-mode')?.value||'core',mapFormat:'battletech',terrainMode:$('#terrain-mode')?.value||'primary',terrain:$('#terrain')?.value||'Grasslands',ownedMapFilter:$('#owned-map-filter')?.checked||false,ownedPacks:$$('.owned-map-pack:checked').map(x=>x.value),compMode:$('#comp-mode')?.value||'random',compChoice:$('#comp-choice')?.value||'No Complication'}}
function log(title,text,result){state.log.push({title,text,result})}
const NO_RANDOM_DURATION=new Set(['Ambush','Annihilation','Dominate']);
function randomDurationAllowed(m){return !NO_RANDOM_DURATION.has(m.name)}
function build(){state.config=config();const c=state.config,pool=c.scale<=2?MISSIONS.slice(0,6):MISSIONS;let m;if(c.selection==='manual'){m=pool.find(x=>x.name===c.manual)||pool[0];log('Mission selection','Manual mission selection — no mission die rolled.',m.name)}else if(c.scale<=2){const a=roll(6);m=pool[a-1];log('Mission selection','Scale 1–2: one 1D6 applied to Ambush through General Melee.',`1D6 = ${a} · ${m.name}`)}else{const a=roll(6),b=roll(6);m=pool[(a-1)*6+b-1];log('Mission selection','Two-sided Standard Mission Table: first roll chooses the group, second chooses the mission.',`1D6 = ${a}, 1D6 = ${b} · ${m.name}`)}state.mission=m;const d=m.comp==='master'?roll(6)+roll(6):roll(6),table=m.comp==='master'?MASTER:RESTRICTED;let comp=table[d],guard=0;while(comp==='Random Duration'&&!randomDurationAllowed(m)&&guard++<20){const r=m.comp==='master'?roll(6)+roll(6):roll(6);log('Complication reroll','This mission does not use Random Duration; reroll the same complications table.',`${m.comp==='master'?'2D6':'1D6'} = ${r}`);comp=table[r]}log('Complication',`${m.comp==='master'?'Master (2D6)':'Restricted (1D6)'} Complications Table${m.note?' · '+m.note:''}`,`${m.comp==='master'?'2D6':'1D6'} = ${d} · ${comp}`);if(m.name==='Annihilation'&&roll(6)>=4){let extra=MASTER[roll(6)+roll(6)],extraGuard=0;while((extra==='Random Duration'||extra===comp)&&extraGuard++<20)extra=MASTER[roll(6)+roll(6)];log('Additional complication','Annihilation calls for a second Master Complication on 4+; duplicates, Random Duration, and a second Edge/Fog type are rerolled.','Additional Master result · '+extra)}if(comp==='Battlefield Conditions'){const r=roll(6)+roll(6);let details=CONDITIONS[r];if(r===7){const second=roll(6)+roll(6);details+='; second roll '+second+' · '+CONDITIONS[second]}if([2,3,11,12].includes(r)){const level=roll(6);details+=`; level roll 1D6 = ${level} → ${level<=3?1:level<=5?2:3}`}if(r===9){const level=roll(6);details+=`; level roll 1D6 = ${level} → ${[0.5,0.8,1.2,1.5,1.5,2][level-1]}`}log('Battlefield condition','Roll 2D6 on the Battlefield Conditions Table and resolve its conditional roll(s).',`2D6 = ${r} · ${details}`)}if(comp==='Random Duration')log('Random duration','At the start of Turn 7, then Turns 8–9, then Turn 10 onward, roll as specified until the mission ends.','See p. 233');if(comp==='Waves')log('Waves','Default: half of each force withheld; one wave; begin rolling on Turn 2.','See p. 233');renderGeneration();renderSheet();renderRelatedRules();show('generate')}
function show(which){document.body.classList.toggle('work-view',which!=='configure');$$('.view').forEach(v=>v.classList.remove('active-view'));$(`#view-${which}`).classList.add('active-view');$$('.step').forEach(s=>s.classList.toggle('active',s.dataset.step===which));window.scrollTo({top:0,behavior:'smooth'})}
function renderGeneration(){const c=state.config,m=state.mission;$('#generation-summary').innerHTML=`<div class="summary-cell"><small>Mission</small><strong>${m.name}</strong></div><div class="summary-cell"><small>Scale</small><strong>${c.scale} / ${fmt(c.scale*2000)} BV</strong></div><div class="summary-cell"><small>Complications</small><strong>${m.comp[0].toUpperCase()+m.comp.slice(1)}</strong></div><div class="summary-cell"><small>Mode</small><strong>${c.selection==='random'?'Random':'Manual'}</strong></div>`;$('#roll-log').innerHTML=state.log.map((x,i)=>`<article class="roll-card"><div class="roll-num">${String(i+1).padStart(2,'0')}</div><div><h4>${x.title}</h4><p>${x.text}</p></div><div class="roll-result">${x.result}</div></article>`).join('')}
function decisions(){const m=state.mission,c=state.config;return[...m.decisions,...(c.options.includes('variant-setup')?['Use Variant Mission Setup: lowest-BV force is Defender; Attacker chooses two missions; Defender chooses one; Attacker chooses maps; Defender chooses home edge.']:[]),...(c.options.includes('forced-withdrawal')?['Apply Forced Withdrawal and Crippled rules as written on p. 230.']:[]),...(c.options.includes('enhanced-probes')?['Apply Enhanced Probes only if all players agreed before play.']:[]),...(c.options.includes('unit-vp-control')?['Use Unit Victory Point Control for objective contests.']:[])]}
function renderSheet(){const m=state.mission,c=state.config,label=c.compMode==='pick'?'Player choice':'Generated outcome',out=state.log.filter(x=>['Complication','Battlefield condition','Random duration','Waves'].includes(x.title)).map(x=>`<div class="outcome"><strong>${label}</strong><p>${x.title}: ${x.result}. ${x.text}</p></div>`).join(''),dec=decisions().map(x=>`<li>${x}</li>`).join('');$('#mission-sheet').innerHTML=`<div class="mission-hero"><div class="eyebrow">STANDARD MISSION / ${m.pages}</div><h2>${m.name}</h2><p>${m.setup}</p><div class="mission-meta"><span class="meta-pill">Scale ${c.scale}</span><span class="meta-pill">${fmt(c.scale*2000)} BV / side</span><span class="meta-pill">${m.duration}</span><span class="meta-pill">${c.bfs?'BFS enabled':'BFS off'}</span></div></div><div class="sheet-grid"><article class="sheet-card"><h3>Generated results</h3>${out||'<div class="outcome"><strong>Generated outcome</strong><p>No additional complication result was rolled.</p></div>'}<p class="reference">Core Rulebook pp. 213, 229–230; mission-specific rules ${m.refs}.</p></article><article class="sheet-card"><h3>Players still decide</h3><ul>${dec}</ul><p class="reference">Map and objective choices follow pp. 223–224 and the mission entry.</p></article><article class="sheet-card full"><h3>Setup & deployment</h3><div class="outcome"><strong>Setup</strong><p>${m.setup}</p></div><div class="outcome"><strong>Objective counters</strong><p>${m.objectives}</p></div><div class="outcome"><strong>Deployment</strong><p>${m.deployment}</p></div><p class="reference">Core Rulebook ${m.refs}. Standard setup/deployment: pp. 212–213, 223–224.</p></article><article class="sheet-card full"><h3>Victory conditions</h3><p>${m.victory}</p><p class="reference">Victory conditions and VP procedures: pp. 225–227; mission-specific text: ${m.refs}.</p>${c.options.includes('forced-withdrawal')?'<div class="decision"><strong>Optional rule active</strong><p>Forced Withdrawal is selected. Crippled units and withdrawal scoring use p. 230.</p></div>':''}${['Extraction','Focal Point'].includes(m.name)?'<div class="ambiguity"><strong>Terrain contingency</strong><p>If a required Hex 1509 placement is inaccessible, use the nearest non-violating hex under the objective-placement guidance. The generator cannot inspect your physical map.</p></div>':''}</article></div>`}
function syncManualOptions(){const limit=(Number($('#scale').value)||3)<=2?6:12,current=$('#manual-mission').value;$('#manual-mission').innerHTML=MISSIONS.slice(0,limit).map(m=>`<option value="${m.name}">${m.name} · ${m.pages}</option>`).join('');if([...$('#manual-mission').options].some(o=>o.value===current))$('#manual-mission').value=current}
function init(){syncManualOptions();$('#scale').addEventListener('input',()=>{$('#bv-readout').textContent=fmt(Math.max(1,Number($('#scale').value)||3)*2000)+' BV';syncManualOptions()});$$('input[name="selection"]').forEach(x=>x.addEventListener('change',()=>$('#manual-mission-wrap').classList.toggle('hidden-field',x.value!=='manual'||!x.checked)));$('#bfs').addEventListener('change',e=>$('#bfs-note').classList.toggle('hidden-field',!e.target.checked));$('#generate-btn').addEventListener('click',()=>{state.log=[];build()});$('#back-config').addEventListener('click',()=>show('configure'));$('#open-sheet').addEventListener('click',()=>show('sheet'));$('#reroll').addEventListener('click',()=>{state.log=[];build()});$('#sheet-config').addEventListener('click',()=>show('configure'));$('#save-pdf').addEventListener('click',()=>window.openPrintDocument?window.openPrintDocument():window.print());$$('.step').forEach(s=>s.addEventListener('click',()=>{if(s.dataset.step==='configure')show('configure');if(s.dataset.step==='sheet'&&state.mission){renderSheet();renderRelatedRules();show('sheet')}if(s.dataset.step==='generate'&&state.mission){renderGeneration();show('generate')}}))}init();
function renderRelatedRules(){if(!state.mission||document.querySelector('#related-rules'))return;const c=state.config,m=state.mission,items=[['Force building & BV','Spend up to the Scale allotment per side, including skill upgrades and any selected BFS purchases. BV cannot be exceeded.','pp. 212, 218–219'],['Maps & home edges','Standard Missions assume two mapsheets. The map selector chooses the map(s); the other side chooses a home edge unless the mission says otherwise.','pp. 212–213, 223–224'],['Movement onto the battlefield','Standard deployment uses Initiative, then forces move onto the field from home edges. Mission-specific deployment overrides it.','pp. 213, 223–224'],['Victory Points','After the last turn, total VPs. Objective VP and Unit VP are not normally combined except as a tiebreaker.','pp. 225–227'],['Scanning & probes','Default scanning range is 2 hexes with line of sight; scanning is a sensor check with +3 TN. Active probes modify range and TN.','p. 233'],['Objectives','Control uses non-crippled units within the stated radius. Mobile, Fragile, and Potential variants have additional procedures.','pp. 231–233']];if(c.bfs)items.push(['Battlefield Support','If used, players may convert BV to BSP at 20 BV per 1 BSP, or use the applicable BFS force-building method.','pp. 157, 219']);if(c.options.includes('forced-withdrawal'))items.push(['Forced Withdrawal','Crippled units must retreat under the movement and surrender conditions; Forced Withdrawal also enables Crippled status.','p. 230']);if(c.options.includes('enhanced-probes'))items.push(['Enhanced Probes','Probe detection remains active throughout movement instead of only resolving at its end.','p. 230']);if(c.options.includes('unit-vp-control'))items.push(['Unit Victory Point Control','This optional rule changes how ’Mechs contest Assets and non-’Mech units at objectives.','p. 232']);if(c.options.includes('variant-setup'))items.push(['Variant Mission Setup','This optional setup changes Attacker/Defender, mission, map, and home-edge selection order.','p. 213']);if(state.log.some(x=>x.title==='Battlefield condition'))items.push(['Battlefield Conditions','The generated condition lasts for the mission; resolve its listed environmental effects from the Conditions rules.','pp. 120–121, 227']);if(state.log.some(x=>x.title==='Random duration'))items.push(['Random Duration','Roll at the start of Turn 7, Turns 8–9, and Turn 10 onward using the thresholds on p. 233.','p. 233']);if(state.log.some(x=>x.title==='Waves'))items.push(['Waves','Withheld units roll for arrival beginning on the designated turn; defaults are half the force, one wave, Turn 2.','p. 233']);if(['Ambush','Steel Rain'].includes(m.name))items.push(['Combat Drop','Dropped ’Mechs follow the mission’s arrival and deployment instructions; Assets cannot Combat Drop.','p. 227']);$('#mission-sheet').insertAdjacentHTML('beforeend',`<article id="related-rules" class="sheet-card full"><h3>Related rules to have open</h3><div class="related-rules">${items.map(x=>`<div class="related-rule"><strong>${x[0]}</strong><p>${x[1]}</p><span>${x[2]}</span></div>`).join('')}</div></article>`)}
